<script setup>import SafeImage from '../components/common/SafeImage.vue';defineProps({tab:String,orders:Array,services:Array,actionError:String});defineEmits(['change-tab','update-order','return-home'])</script><template><aside class="admin-aside"><a class="brand" href="#/">贵州乌东 · 运营</a><button :class="{active:tab==='orders'}" @click="$emit('change-tab','orders')">预约订单</button><button :class="{active:tab==='content'}" @click="$emit('change-tab','content')">资源与社区</button><button :class="{active:tab==='ai-summary'}" @click="$emit('change-tab','ai-summary')">AI 运行摘要</button><button @click="$emit('return-home')">返回游客端</button></aside><main class="admin-main"><header class="admin-head"><div><p class="eyebrow">本机答辩演示后台</p><h1>{{tab==='orders'?'预约订单':tab==='content'?'资源与社区':'AI 运行摘要'}}</h1></div><span class="demo-badge">演示数据</span></header><p v-if="actionError">{{actionError}}</p><section v-if="tab==='orders'" class="admin-table"><div class="table-row header"><span>体验项目</span><span>日期 / 人数</span><span>状态</span><span>操作</span></div><div v-for="order in orders" :key="order.id" class="table-row"><span>{{order.name}}</span><span>{{order.date}} · {{order.people}} 人</span><span>{{order.status}}</span><button v-if="order.status==='CONFIRMED'||order.status==='PROCESSING'" @click="$emit('update-order',order)">更新状态</button></div></section><section v-else-if="tab==='content'" class="admin-content"><article v-for="item in services" :key="item.id" class="admin-resource"><SafeImage :src="item.image" :alt="item.imageAlt" :label="item.title" loading="lazy"/><h3>{{item.title}}</h3></article></section><section v-else class="trace-list"><h2>演示摘要，不对应本次会话 / 非 LangSmith Trace。</h2><p>向导会按需求理解、知识检索、服务协同、行程生成四个阶段组织结果。</p></section></main></template>
